1: import { useEffect, useRef, useState } from "react";
2: import * as THREE from "three";
3: import { OrbitControls } from "three/addons/controls/OrbitControls.js";
4: import { cx } from "@/lib/cx";
5: import { label } from "./classify";
6: import { buildCar, type CarPiece } from "./model/buildCar";
7: import { G60 } from "./model/body";
8: import {
9:   applyState,
10:   createOutlineMaterial,
11:   createPieceStyle,
12:   OUTLINED,
13:   readPalette,
14:   type PartState,
15:   type PieceStyle,
16:   type SketchPalette,
17: } from "./model/sketch";
18: 
19: export type CarView = "exterior" | "interior";
20: export type CameraPreset = "front" | "side" | "rear" | "top";
21: 
22: const PRESETS: Record<
23:   CameraPreset,
24:   { position: [number, number, number]; target: [number, number, number] }
25: > = {
26:   front: { position: [5.0, 2.1, -5.2], target: [0, 0.68, 0] },
27:   side: { position: [0, 1.1, -7.6], target: [0, 0.7, 0] },
28:   rear: { position: [-5.2, 2.3, -4.6], target: [0, 0.68, 0] },
29:   top: { position: [0.01, 8.4, -0.4], target: [0, 0.5, 0] },
30: };
31: 
32: const UNGHOSTED_KINDS = new Set(["tyre", "rim", "metal", "accent"]);
33: 
34: interface Props {
35:   /** Requirements per part id (only parts with ≥ 1 are badged and tinted). */
36:   counts: ReadonlyMap<string, number>;
37:   selected: string | null;
38:   view: CarView;
39:   preset: CameraPreset;
40:   /** Bumped to move the camera to `preset` again. */
41:   presetNonce: number;
42:   onSelect: (partId: string | null) => void;
43: }
44: 
45: /**
46:  * The 3D car: drag to orbit, scroll to zoom, right-drag to pan. Hover shows the part's name, a click
47:  * selects it. Parts with requirements carry a badge with the count; badges are clickable too.
48:  */
49: export function CarViewer(props: Props) {
50:   const hostRef = useRef<HTMLDivElement>(null);
51:   const tooltipRef = useRef<HTMLDivElement>(null);
52:   const badgeRefs = useRef(new Map<string, HTMLButtonElement>());
53:   const propsRef = useRef(props);
54:   propsRef.current = props;
55:   const apiRef = useRef<{ restyle: () => void; moveTo: (p: CameraPreset) => void } | null>(null);
56:   const [hovered, setHovered] = useState<string | null>(null);
57:   const [failed, setFailed] = useState<string | null>(null);
58:   const [anchors, setAnchors] = useState<ReadonlyMap<string, THREE.Vector3>>(new Map());
59: 
60:   useEffect(() => {
61:     const host = hostRef.current;
62:     if (!host) return;
63: 
64:     let renderer: THREE.WebGLRenderer;
65:     try {
66:       renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
67:     } catch (e) {
68:       setFailed(e instanceof Error ? e.message : "WebGL is not available");
69:       return;
70:     }
71:     renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
72:     renderer.domElement.dataset.testid = "car-canvas";
73:     renderer.domElement.style.display = "block";
74:     host.appendChild(renderer.domElement);
75: 
76:     const scene = new THREE.Scene();
77:     const camera = new THREE.PerspectiveCamera(32, 1, 0.05, 100);
78:     camera.position.set(...PRESETS.front.position);
79:     const controls = new OrbitControls(camera, renderer.domElement);
80:     controls.target.set(...PRESETS.front.target);
81:     controls.enableDamping = true;
82:     controls.dampingFactor = 0.08;
83:     controls.minDistance = 2.2;
84:     controls.maxDistance = 16;
85:     controls.maxPolarAngle = Math.PI * 0.495;
86:     controls.update();
87: 
88:     const car = buildCar();
89:     scene.add(car.root);
90:     setAnchors(car.anchors);
91:     const bounds = new THREE.Box3().setFromObject(car.root);
92:     const corners: THREE.Vector3[] = [];
93:     for (const x of [bounds.min.x, bounds.max.x]) {
94:       for (const y of [bounds.min.y, bounds.max.y]) {
95:         for (const z of [bounds.min.z, bounds.max.z]) corners.push(new THREE.Vector3(x, y, z));
96:       }
97:     }
98:     const fittedPosition = (preset: CameraPreset) => {
99:       const target = new THREE.Vector3(...PRESETS[preset].target);
100:       const direction = new THREE.Vector3(...PRESETS[preset].position).sub(target).normalize();
101:       const right = new THREE.Vector3().crossVectors(camera.up, direction).normalize();
102:       const up = new THREE.Vector3().crossVectors(direction, right);
103:       const tanV = Math.tan(THREE.MathUtils.degToRad(camera.fov / 2));
104:       const tanH = tanV * camera.aspect;
105:       let distance = 0;
106:       for (const corner of corners) {
107:         const delta = corner.clone().sub(target);
108:         distance = Math.max(
109:           distance,
110:           delta.dot(direction) +
111:             Math.max(Math.abs(delta.dot(right)) / tanH, Math.abs(delta.dot(up)) / tanV),
112:         );
113:       }
114:       return target.addScaledVector(direction, distance * 1.12);
115:     };
116: 
117:     let palette: SketchPalette = readPalette();
118:     const outline = createOutlineMaterial(palette.ink, 1.4);
119:     const styles = new Map<CarPiece, PieceStyle>();
120:     const outlines = new Map<CarPiece, THREE.Mesh>();
121:     const pickable: THREE.Mesh[] = [];
122: 
123:     for (const piece of car.pieces) {
124:       const style = createPieceStyle(piece, palette);
125:       (piece.mesh.material as THREE.Material).dispose();
126:       piece.mesh.material = style.fill;
127:       styles.set(piece, style);
128:       // The body already has explicit panel/character lines and a silhouette.
129:       // Drawing tessellation creases adds stray spikes around the wheel arches.
130:       const threshold = piece.kind === "paint" || piece.kind === "glass" ? 180 : 40;
131:       const edgeGeometry = new THREE.EdgesGeometry(piece.mesh.geometry, threshold);
132:       const hasArches =
133:         piece.kind === "paint" &&
134:         ["body", "front_doors", "rear_doors"].includes(piece.partId ?? "");
135:       if (hasArches) {
136:         // Arch contours are drawn as smooth projected arcs, rather than the
137:         // cut grid's many inner and outer boundary segments.
138:         const positions = edgeGeometry.getAttribute("position");
139:         const clean: number[] = [];
140:         for (let k = 0; k < positions.count; k += 2) {
141:           const nearArch = [k, k + 1].some((v) =>
142:             [G60.frontAxleX, G60.rearAxleX].some(
143:               (axle) =>
144:                 Math.hypot(positions.getX(v) - axle, positions.getY(v) - G60.tyreRadius) <
145:                 G60.archRadius + 0.035,
146:             ),
147:           );
148:           if (nearArch) continue;
149:           for (const v of [k, k + 1])
150:             clean.push(positions.getX(v), positions.getY(v), positions.getZ(v));
151:         }
152:         edgeGeometry.setAttribute("position", new THREE.Float32BufferAttribute(clean, 3));
153:       }
154:       const edges = new THREE.LineSegments(edgeGeometry, style.lines);
155:       edges.raycast = () => {};
156:       piece.mesh.add(edges);
157:       // Inverted hulls work on closed solids. On open body panels they expose
158:       // their back faces through arch openings and turn the triangulation into ink.
159:       if (
160:         OUTLINED.has(piece.kind) &&
161:         (!piece.mesh.geometry.userData.openSurface || (piece.kind === "paint" && !hasArches))
162:       ) {
163:         const hull = new THREE.Mesh(piece.mesh.geometry, outline);
164:         hull.raycast = () => {};
165:         piece.mesh.add(hull);
166:         outlines.set(piece, hull);
167:       }
168:     }
169:     const sketchMat = new THREE.LineBasicMaterial({
170:       color: palette.ink,
171:       transparent: true,
172:       opacity: 0.35,
173:     });
174:     for (const geo of car.sketchLines) scene.add(new THREE.LineSegments(geo, sketchMat));
175: 
176:     let hoveredPart: string | null = null;
177:     let dirty = true;
178: 
179:     const restyle = () => {
180:       const { counts, selected, view } = propsRef.current;
181:       scene.background = palette.background;
182:       outline.uniforms.color!.value.copy(palette.ink);
183:       sketchMat.color.copy(palette.ink);
184:       sketchMat.opacity = view === "interior" ? 0.08 : 0.35;
185:       pickable.length = 0;
186:       for (const piece of car.pieces) {
187:         const state: PartState =
188:           piece.partId && piece.partId === selected
189:             ? "selected"
190:             : piece.partId && piece.partId === hoveredPart
191:               ? "hover"
192:               : piece.partId && (counts.get(piece.partId) ?? 0) > 0
193:                 ? "hasRequirements"
194:                 : "idle";
195:         const ghost =
196:           view === "interior" && piece.layer === "exterior" && !UNGHOSTED_KINDS.has(piece.kind);
197:         const canPick = applyState(piece, styles.get(piece)!, state, ghost, palette);
198:         const hull = outlines.get(piece);
199:         if (hull) hull.visible = !ghost;
200:         if (canPick) pickable.push(piece.mesh);
201:       }
202:       dirty = true;
203:     };
204: 
205:     const onTheme = new MutationObserver(() => {
206:       palette = readPalette();
207:       restyle();
208:     });
209:     onTheme.observe(document.documentElement, {
210:       attributes: true,
211:       attributeFilter: ["data-theme"],
212:     });
213: 
214:     // Camera moves between presets.
215:     let flight: {
216:       from: THREE.Vector3;
217:       to: THREE.Vector3;
218:       fromT: THREE.Vector3;
219:       toT: THREE.Vector3;
220:       t0: number;
221:     } | null = null;
222:     let activePreset: CameraPreset | null = propsRef.current.preset;
223:     const moveTo = (preset: CameraPreset) => {
224:       const p = PRESETS[preset];
225:       activePreset = preset;
226:       flight = {
227:         from: camera.position.clone(),
228:         to: fittedPosition(preset),
229:         fromT: controls.target.clone(),
230:         toT: new THREE.Vector3(...p.target),
231:         t0: performance.now(),
232:       };
233:     };
234:     const onOrbitStart = () => {
235:       flight = null;
236:       activePreset = null;
237:     };
238:     controls.addEventListener("start", onOrbitStart);
239:     apiRef.current = { restyle, moveTo };
240: 
241:     // Picking.
242:     const raycaster = new THREE.Raycaster();
243:     const pointer = new THREE.Vector2();
244:     let pointerInside = false;
245:     let pointerPx = { x: 0, y: 0 };
246:     let needsPick = false;
247:     const pick = (): string | null => {
248:       raycaster.setFromCamera(pointer, camera);
249:       const hit = raycaster.intersectObjects(pickable, false)[0];
250:       return (hit?.object.userData.partId as string | null | undefined) ?? null;
251:     };
252:     const setPointer = (e: PointerEvent) => {
253:       const r = renderer.domElement.getBoundingClientRect();
254:       pointerPx = { x: e.clientX - r.left, y: e.clientY - r.top };
255:       pointer.set((pointerPx.x / r.width) * 2 - 1, -(pointerPx.y / r.height) * 2 + 1);
256:     };
257:     let down: { x: number; y: number } | null = null;
258:     const onMove = (e: PointerEvent) => {
259:       setPointer(e);
260:       pointerInside = true;
261:       needsPick = true;
262:     };
263:     const onLeave = () => {
264:       pointerInside = false;
265:       needsPick = true;
266:     };
267:     const onDown = (e: PointerEvent) => {
268:       down = { x: e.clientX, y: e.clientY };
269:     };
270:     const onUp = (e: PointerEvent) => {
271:       if (!down || e.button !== 0) return;
272:       const moved = Math.hypot(e.clientX - down.x, e.clientY - down.y);
273:       down = null;
274:       if (moved > 5) return;
275:       setPointer(e);
276:       propsRef.current.onSelect(pick());
277:     };
278:     const el = renderer.domElement;
279:     el.addEventListener("pointermove", onMove);
280:     el.addEventListener("pointerleave", onLeave);
281:     el.addEventListener("pointerdown", onDown);
282:     el.addEventListener("pointerup", onUp);
283: 
284:     const resize = () => {
285:       const { clientWidth: w, clientHeight: h } = host;
286:       if (w === 0 || h === 0) return;
287:       renderer.setSize(w, h, false);
288:       renderer.domElement.style.width = `${w}px`;
289:       renderer.domElement.style.height = `${h}px`;
290:       camera.aspect = w / h;
291:       camera.updateProjectionMatrix();
292:       if (activePreset) {
293:         const position = fittedPosition(activePreset);
294:         controls.maxDistance = Math.max(16, position.distanceTo(controls.target) * 1.5);
295:         if (flight) flight.to.copy(position);
296:         else camera.position.copy(position);
297:       }
298:       const size = renderer.getDrawingBufferSize(new THREE.Vector2());
299:       outline.uniforms.resolution!.value.copy(size);
300:       outline.uniforms.width!.value = 1.4 * renderer.getPixelRatio();
301:       dirty = true;
302:     };
303:     const ro = new ResizeObserver(resize);
304:     ro.observe(host);
305:     resize();
306:     restyle();
307: 
308:     // Render loop: only draws when something changed.
309:     const v = new THREE.Vector3();
310:     let frame = 0;
311:     const loop = () => {
312:       frame = requestAnimationFrame(loop);
313:       if (flight) {
314:         const t = Math.min(1, (performance.now() - flight.t0) / 650);
315:         const e = t < 0.5 ? 2 * t * t : 1 - (-2 * t + 2) ** 2 / 2;
316:         camera.position.lerpVectors(flight.from, flight.to, e);
317:         controls.target.lerpVectors(flight.fromT, flight.toT, e);
318:         if (t >= 1) flight = null;
319:         dirty = true;
320:       }
321:       if (controls.update()) {
322:         dirty = true;
323:         needsPick = true;
324:       }
325:       if (needsPick) {
326:         needsPick = false;
327:         const part = pointerInside ? pick() : null;
328:         if (part !== hoveredPart) {
329:           hoveredPart = part;
330:           setHovered(part);
331:           el.style.cursor = part ? "pointer" : "grab";
332:           restyle();
333:         }
334:       }
335:       const tip = tooltipRef.current;
336:       if (tip) tip.style.transform = `translate(${pointerPx.x + 14}px, ${pointerPx.y + 12}px)`;
337:       if (!dirty) return;
338:       dirty = false;
339:       renderer.render(scene, camera);
340:       // Badges follow their anchors.
341:       const { clientWidth: w, clientHeight: h } = host;
342:       for (const [partId, badge] of badgeRefs.current) {
343:         const anchor = car.anchors.get(partId);
344:         if (!anchor) continue;
345:         v.copy(anchor).project(camera);
346:         const visible = v.z > -1 && v.z < 1 && Math.abs(v.x) < 1.05 && Math.abs(v.y) < 1.05;
347:         badge.style.visibility = visible ? "visible" : "hidden";
348:         badge.style.transform = `translate(${((v.x + 1) / 2) * w}px, ${((1 - v.y) / 2) * h}px) translate(-50%, -50%)`;
349:       }
350:     };
351:     loop();
352: 
353:     return () => {
354:       cancelAnimationFrame(frame);
355:       ro.disconnect();
356:       onTheme.disconnect();
357:       el.removeEventListener("pointermove", onMove);
358:       el.removeEventListener("pointerleave", onLeave);
359:       el.removeEventListener("pointerdown", onDown);
360:       el.removeEventListener("pointerup", onUp);
361:       controls.removeEventListener("start", onOrbitStart);
362:       controls.dispose();
363:       const geometries = new Set<THREE.BufferGeometry>();
364:       scene.traverse((o) => {
365:         if (o instanceof THREE.Mesh || o instanceof THREE.LineSegments) geometries.add(o.geometry);
366:       });
367:       for (const geometry of geometries) geometry.dispose();
368:       for (const s of styles.values()) {
369:         s.fill.dispose();
370:         s.lines.dispose();
371:       }
372:       outline.dispose();
373:       sketchMat.dispose();
374:       renderer.dispose();
375:       renderer.domElement.remove();
376:       apiRef.current = null;
377:     };
378:   }, []);
379: 
380:   // React to selection, counts and view changes without rebuilding the scene.
381:   useEffect(() => {
382:     apiRef.current?.restyle();
383:   }, [props.counts, props.selected, props.view]);
384: 
385:   useEffect(() => {
386:     apiRef.current?.moveTo(props.preset);
387:   }, [props.preset, props.presetNonce]);
388: 
389:   if (failed) {
390:     return (
391:       <div className="grid h-full place-items-center p-8 text-center text-sm text-muted">
392:         <p>
393:           The 3D car needs WebGL, which isn't available here ({failed}). Pick a part from the list
394:           instead.
395:         </p>
396:       </div>
397:     );
398:   }
399: 
400:   const badged = [...props.counts.entries()].filter(([id, n]) => n > 0 && anchors.has(id));
401:   return (
402:     <div ref={hostRef} className="relative h-full w-full overflow-hidden" data-testid="car-viewer">
403:       {badged.map(([partId, n]) => (
404:         <button
405:           key={partId}
406:           type="button"
407:           ref={(el) => {
408:             if (el) badgeRefs.current.set(partId, el);
409:             else badgeRefs.current.delete(partId);
410:           }}
411:           onClick={() => props.onSelect(partId)}
412:           data-testid={`car-badge-${partId}`}
413:           title={`${label(partId)}: ${n} requirement${n === 1 ? "" : "s"}`}
414:           className={cx(
415:             "absolute top-0 left-0 grid h-6 min-w-6 place-items-center rounded-full border px-1.5 text-xs font-semibold shadow-sm transition-colors",
416:             props.selected === partId
417:               ? "border-brand bg-brand-fill text-white"
418:               : "border-line bg-panel text-ink hover:border-brand",
419:           )}
420:           style={{ visibility: "hidden" }}
421:         >
422:           {n}
423:         </button>
424:       ))}
425:       <div
426:         ref={tooltipRef}
427:         className={cx(
428:           "pointer-events-none absolute top-0 left-0 rounded-md border border-line bg-panel px-2 py-1 text-xs font-medium text-ink shadow-sm",
429:           hovered ? "opacity-100" : "opacity-0",
430:         )}
431:       >
432:         {hovered ? label(hovered) : ""}
433:       </div>
434:     </div>
435:   );
436: }

