55:             BMW {scope.vehicleLine}
56:             {scope.derivative ? ` ${scope.derivative}` : ""}
57:             <span className="text-sm font-normal text-muted">
58:               {scope.market} · {scope.horizonYears}-year horizon
59:             </span>
60:           </span>
61:         }
