63:           <>
64:             <Segmented options={VIEWS} value={view} onChange={setView} testIdPrefix="car-view-" />
65:             <div className="flex items-center gap-1">
66:               {PRESETS.map((p) => (
67:                 <Button
68:                   key={p.value}
69:                   size="sm"
70:                   variant={preset === p.value ? "secondary" : "ghost"}
71:                   data-testid={`car-camera-${p.value}`}
72:                   onClick={() => {
73:                     setPreset(p.value);
74:                     setPresetNonce((n) => n + 1);
75:                   }}
76:                 >
77:                   {p.label}
78:                 </Button>
79:               ))}
80:             </div>
81:           </>
