707: /** A helix along +y (coil spring). */
708: function helix(radius: number, height: number, turns: number): THREE.Curve<THREE.Vector3> {
709:   const pts: THREE.Vector3[] = [];
710:   const n = turns * 24;
711:   for (let k = 0; k <= n; k++) {
712:     const t = k / n;
713:     const a = t * turns * Math.PI * 2;
714:     pts.push(new THREE.Vector3(Math.cos(a) * radius, t * height, Math.sin(a) * radius));
715:   }
716:   return new THREE.CatmullRomCurve3(pts);
717: }
