719: /** Merges a group's (non-indexed) child geometries into one, in the group's space. */
720: function mergeChildren(group: THREE.Group): THREE.BufferGeometry {
721:   const positions: number[] = [];
722:   const normals: number[] = [];
723:   group.traverse((o) => {
724:     if (!(o instanceof THREE.Mesh)) return;
725:     const source = o.geometry as THREE.BufferGeometry;
726:     const g = source.index ? source.toNonIndexed() : source.clone();
727:     g.applyMatrix4(o.matrixWorld);
728:     positions.push(...(g.getAttribute("position").array as Float32Array));
729:     normals.push(...(g.getAttribute("normal").array as Float32Array));
730:     g.dispose();
731:     source.dispose();
732:     (o.material as THREE.Material).dispose();
733:   });
734:   const merged = new THREE.BufferGeometry();
735:   merged.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
736:   merged.setAttribute("normal", new THREE.Float32BufferAttribute(normals, 3));
737:   return merged;
738: }
