765: function anchorsFor(pieces: CarPiece[]): Map<string, THREE.Vector3> {
766:   const boxes = new Map<string, THREE.Box3>();
767:   for (const { mesh, partId } of pieces) {
768:     if (!partId) continue;
769:     const b = new THREE.Box3().setFromObject(mesh);
770:     const prev = boxes.get(partId);
771:     boxes.set(partId, prev ? prev.union(b) : b);
772:   }
773:   const anchors = new Map<string, THREE.Vector3>();
774:   for (const [partId, b] of boxes) {
775:     const o = ANCHOR_OVERRIDES[partId];
776:     anchors.set(partId, o ? new THREE.Vector3(...o) : b.getCenter(new THREE.Vector3()));
777:   }
778:   return anchors;
779: }

