54: export function createPieceStyle(piece: CarPiece, p: SketchPalette): PieceStyle {
55:   const opacity = SEE_THROUGH.has(piece.kind) ? 0 : 1;
56:   const fill = new THREE.MeshBasicMaterial({
57:     color: p.background,
58:     transparent: opacity < 1,
59:     opacity,
60:     side: THREE.DoubleSide,
61:     depthWrite: opacity >= 1,
62:     polygonOffset: true,
63:     polygonOffsetFactor: 1,
64:     polygonOffsetUnits: 1,
65:   });
