71: /** Applies the part state and view mode to one piece. Returns whether it can be clicked. */
72: export function applyState(
73:   piece: CarPiece,
74:   style: PieceStyle,
75:   state: PartState,
76:   ghost: boolean,
77:   p: SketchPalette,
78: ): boolean {
79:   const base = style.fill.userData.base as { opacity: number };
80:   const active = state === "hover" || state === "selected";
81:   const color = p.background.clone();
82:   if (piece.kind === "glass") color.lerp(p.ink, 0.045);
83:   let opacity = base.opacity;
84:   // Selection is the only colour on the drawing: brand-coloured lines and a faint wash.
85:   if (state === "selected") {
86:     color.copy(p.selection);
87:     opacity = Math.max(opacity, 0.5);
88:   }
89:   let lineOpacity = piece.layer === "interior" ? 0.55 : 0.75;
90:   if (active) lineOpacity = 1;
91:   if (ghost) {
92:     opacity = state === "selected" ? 0.15 : 0;
93:     lineOpacity = active ? 0.8 : 0.14;
94:   }
95:   style.fill.color.copy(color);
96:   style.fill.opacity = opacity;
97:   const transparent = opacity < 1;
98:   if (style.fill.transparent !== transparent) {
99:     style.fill.transparent = transparent;
100:     style.fill.needsUpdate = true;
101:   }
102:   style.fill.depthWrite = opacity >= 1;
103:   style.lines.color.copy(active ? p.brand : p.ink);
104:   style.lines.opacity = piece.kind === "liner" ? 0 : lineOpacity;
105:   return !ghost && piece.partId !== null;
106: }
