109: export function createOutlineMaterial(color: THREE.Color, widthPx: number): THREE.ShaderMaterial {
110:   return new THREE.ShaderMaterial({
111:     side: THREE.BackSide,
112:     uniforms: {
113:       color: { value: color.clone() },
114:       width: { value: widthPx },
115:       resolution: { value: new THREE.Vector2(1, 1) },
116:     },
117:     vertexShader: /* glsl */ `
118:       uniform float width;
119:       uniform vec2 resolution;
120:       void main() {
121:         vec4 clip = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
122:         vec3 n = normalize(normalMatrix * normal);
123:         vec4 clipN = projectionMatrix * vec4(n, 0.0);
124:         vec2 dir = length(clipN.xy) > 1e-5 ? normalize(clipN.xy) : vec2(0.0);
125:         clip.xy += dir * width * 2.0 / resolution * clip.w;
126:         gl_Position = clip;
127:       }
128:     `,
129:     fragmentShader: /* glsl */ `
130:       uniform vec3 color;
131:       void main() { gl_FragColor = vec4(color, 1.0); }
132:     `,
133:   });
134: }

